#!/usr/bin/env python3
# Autonomously generated by an AI agent.
import argparse
import hashlib
import json
import math
from pathlib import Path
import sys


def report_progress(value):
    print(f"MIXXX_BEAT_THIS_PROGRESS {value:.6f}", file=sys.stderr, flush=True)


def predict_with_progress(tracker, signal, sample_rate):
    from beat_this.inference import split_piece

    spect = tracker.signal2spect(signal, sample_rate)
    report_progress(0.2)
    chunks, _ = split_piece(spect, 1500, border_size=6, avoid_short_end=True)
    total = len(chunks)
    del chunks
    completed = 0

    def chunk_completed(_module, _inputs, _output):
        nonlocal completed
        completed += 1
        report_progress(0.2 + 0.75 * min(completed / total, 1))

    hook = tracker.model.register_forward_hook(chunk_completed)
    try:
        beat_logits, downbeat_logits = tracker.spect2frames(spect)
    finally:
        hook.remove()
    result = tracker.frames2beats(beat_logits, downbeat_logits)
    report_progress(0.98)
    return result


def verify_checkpoint(path, expected_sha256):
    checkpoint = Path(path)
    if not checkpoint.is_file():
        raise ValueError("Model checkpoint does not exist")
    expected = expected_sha256.lower()
    if len(expected) != 64 or any(
        c not in "0123456789abcdef" for c in expected
    ):
        raise ValueError("A valid model SHA-256 is required")
    with checkpoint.open("rb") as stream:
        digest = hashlib.sha256()
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
        actual = digest.hexdigest()
    if actual != expected:
        raise ValueError("Model checkpoint SHA-256 mismatch")
    return checkpoint


def validate_positions(values, duration):
    result = [float(value) for value in values]
    if any(
        not math.isfinite(value) or value < 0 or value > duration + 0.04
        for value in result
    ):
        raise ValueError("Model returned an out-of-range timestamp")
    if any(a >= b for a, b in zip(result, result[1:])):
        raise ValueError("Model timestamps are not strictly increasing")
    # Autonomously generated by an AI agent.
    # Centered STFT padding can produce a prediction at the end boundary.
    # Discard at most two 50 Hz prediction frames outside the actual audio.
    # End of autonomously generated text.
    return [value for value in result if value < duration]


def analyze(args):
    checkpoint = verify_checkpoint(args.checkpoint, args.sha256)
    report_progress(0.01)
    if not 8000 <= args.sample_rate <= 192000:
        raise ValueError("Unsupported sample rate")
    audio_path = Path(args.audio)
    if not audio_path.is_file() or audio_path.stat().st_size % 4:
        raise ValueError("Invalid native float32 mono audio file")
    from importlib.metadata import version

    if version("beat-this") != "1.1.0":
        raise ValueError("This backend requires beat-this 1.1.0")
    import numpy as np
    import torch
    from beat_this.inference import Audio2Beats

    report_progress(0.05)
    torch.set_num_threads(2)
    torch.set_num_interop_threads(1)
    signal = np.memmap(audio_path, dtype=np.float32, mode="r")
    if signal.size == 0 or not np.isfinite(signal).all():
        raise ValueError("Empty or non-finite audio")
    duration = len(signal) / args.sample_rate
    with torch.inference_mode():
        tracker = Audio2Beats(
            checkpoint_path=str(checkpoint), device="cpu", dbn=False
        )
        report_progress(0.1)
        beats, downbeats = predict_with_progress(
            tracker, signal, args.sample_rate
        )
    beats = validate_positions(beats, duration)
    downbeats = validate_positions(downbeats, duration)
    beat_set = set(beats)
    if any(beat not in beat_set for beat in downbeats):
        raise ValueError("Downbeats must be a subset of beats")
    report_progress(1.0)
    return {
        "version": 1,
        "model_sha256": args.sha256.lower(),
        "beats": beats,
        "downbeats": downbeats,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--audio", required=True)
    parser.add_argument("--sample-rate", type=int, required=True)
    parser.add_argument("--checkpoint", required=True)
    parser.add_argument("--sha256", required=True)
    args = parser.parse_args()
    try:
        result = analyze(args)
    except Exception as error:
        print(f"Beat This! analysis failed: {error}", file=sys.stderr)
        return 1
    json.dump(result, sys.stdout, allow_nan=False, separators=(",", ":"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
# End of autonomously generated text.
